css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .84); position: relative; }
.loader .cone { position: absolute; bottom: 0; left: 12%; width: 76%; height: 54%; clip-path: polygon(37% 0, 63% 0, 100% 100%, 0 100%); background: linear-gradient(#475569, #1e293b); }
.loader::after { content: ''; position: absolute; bottom: 50%; left: 40%; width: 20%; height: 8%; border-radius: 50%; background: var(--accent); animation: crater calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader span { position: absolute; bottom: 52%; left: 46%; width: 9%; height: 9%; border-radius: 50%; background: radial-gradient(circle at 38% 32%, color-mix(in srgb, #fff 45%, var(--accent-2)), var(--accent)); animation: erupt calc(var(--loader-speed) * 1.8) ease-out infinite; }
.loader span:nth-child(1) { --sx: -1; }
.loader span:nth-child(2) { --sx: .25; animation-delay: calc(var(--loader-speed) * .6); }
.loader span:nth-child(3) { --sx: 1; animation-delay: calc(var(--loader-speed) * 1.2); }
@keyframes erupt { 0% { opacity: 0; transform: translate(0, 0) scale(.4); } 14% { opacity: 1; } 44% { transform: translate(calc(var(--loader-size) * .1 * var(--sx)), calc(var(--loader-size) * -.34)) scale(1); } 100% { opacity: 0; transform: translate(calc(var(--loader-size) * .28 * var(--sx)), calc(var(--loader-size) * .1)) scale(.65); } }
@keyframes crater { 0%, 100% { box-shadow: 0 0 calc(var(--loader-size) * .05) var(--accent); } 50% { box-shadow: 0 0 calc(var(--loader-size) * .16) var(--accent-2); } }
